const $=s=>document.querySelector(s),tok=s=>s.toLowerCase().match(/[a-z0-9]+/g)||[];
export function rank(data,query,mode='hybrid',alpha=.5,topic='',year=2015){
 const n=data.papers.length,docs=data.papers.map(p=>tok(p.title+' '+p.summary)),counts=docs.map(d=>d.reduce((a,w)=>(a[w]=(a[w]||0)+1,a),{})),avg=docs.reduce((a,d)=>a+d.length,0)/n;
 const terms=[...new Set(tok(query))],b=docs.map((d,i)=>terms.reduce((a,w)=>{const df=counts.filter(c=>c[w]).length,tf=counts[i][w]||0;return a+Math.log(1+(n-df+.5)/(df+.5))*tf*2.5/(tf+1.5*(.25+.75*d.length/avg))},0));
 const tf=tok(query).reduce((a,w)=>(a[w]=(a[w]||0)+1,a),{}),x=Array(data.idf.length).fill(0);
 for(const [w,c]of Object.entries(tf)){const j=data.vocabulary[w];if(j!==undefined)x[j]=c*data.idf[j]}
 const norm=Math.hypot(...x)||1;for(let j=0;j<x.length;j++)x[j]/=norm;
 const q=data.components.map(row=>row.reduce((a,c,j)=>a+c*x[j],0)),qn=Math.hypot(...q)||1,s=data.vectors.map(v=>v.reduce((a,c,j)=>a+c*q[j]/qn,0));
 const eligible=data.papers.map((p,i)=>i).filter(i=>(!topic||data.papers[i].topic===topic)&&data.papers[i].year>=year),sort=scores=>eligible.filter(i=>scores[i]>1e-10).sort((i,j)=>scores[j]-scores[i]||data.papers[i].id.localeCompare(data.papers[j].id)),fusion=Array(n).fill(0);
 sort(b).forEach((i,r)=>fusion[i]+=(1-alpha)/(61+r));sort(s).forEach((i,r)=>fusion[i]+=alpha/(61+r));const scores=mode==='bm25'?b:mode==='semantic'?s:fusion;
 return sort(scores).slice(0,10).map(i=>({...data.papers[i],score:scores[i],bm25:b[i],semantic:s[i]}));
}
let data;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function search(){if(!data)return;const start=performance.now(),results=rank(data,$('#q').value,$('#mode').value,+$('#alpha').value,$('#topic').value,+$('#year').value);$('#weight').textContent=Math.round(+$('#alpha').value*100)+'%';$('#status').textContent=results.length+' papers found';$('#timing').textContent=(performance.now()-start).toFixed(1)+' ms · local search';$('#results').innerHTML=results.length?results.map((p,i)=>`<article class="paper"><span class="rank">${String(i+1).padStart(2,'0')}</span><div><span class="meta">${p.year}</span><span class="tag">${escape(p.topic)}</span><h3><a href="${escape(p.url)}" target="_blank" rel="noopener noreferrer">${escape(p.title)}</a></h3><p>${escape(p.summary)}</p><details><summary>Retrieval scores</summary><div class="scores"><span>Ranking: ${p.score.toFixed(5)}</span><span>BM25: ${p.bm25.toFixed(3)}</span><span>LSA cosine: ${p.semantic.toFixed(3)}</span></div></details></div></article>`).join(''):'<article class="paper"><div></div><div><h3>No matching papers</h3><p>Try different words or widen your research area and year filters.</p></div></article>';return results;}
async function init(){try{const response=await fetch('data.json');if(!response.ok)throw Error('Collection unavailable');data=await response.json();for(const t of [...new Set(data.papers.map(p=>p.topic))].sort()){const o=document.createElement('option');o.value=t;o.textContent=t;$('#topic').append(o)}$('#search').onsubmit=e=>{e.preventDefault();search()};for(const id of ['mode','alpha','topic','year'])$('#'+id).addEventListener('input',search);document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{$('#q').value=b.dataset.q;search()});$('#bench').onclick=()=>$('#evaluation').showModal();$('#close').onclick=()=>$('#evaluation').close();$('#table').innerHTML='<table><thead><tr><th>Method</th><th>Recall@10</th><th>nDCG@10</th><th>MRR@10</th></tr></thead><tbody>'+data.evaluation.results.map(r=>`<tr><td>${r.mode==='semantic'?'LSA':r.mode.toUpperCase()}</td><td>${r.recall_at_k.toFixed(3)}</td><td>${r.ndcg_at_k.toFixed(3)}</td><td>${r.mrr_at_k.toFixed(3)}</td></tr>`).join('')+'</tbody></table>';search();}catch(e){$('#status').textContent='Could not load collection';$('#results').textContent=e.message;}}
if(typeof document!=='undefined')init();
if(typeof document!=='undefined' && document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const tool={name:'search_papers',title:'Search research papers',description:'Search the paper collection and update visible query and results.',inputSchema:{type:'object',properties:{query:{type:'string'},mode:{type:'string',enum:['hybrid','bm25','semantic']}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string'||!input.query.trim()||input.query.length>2000||Object.keys(input).some(k=>!['query','mode'].includes(k))||(input.mode&&!['hybrid','bm25','semantic'].includes(input.mode)))throw Error('Provide a nonempty query and a supported ranking mode');if(!data)throw Error('Collection is still loading');$('#q').value=input.query;if(input.mode)$('#mode').value=input.mode;return {results:search().map(p=>({id:p.id,title:p.title,url:p.url}))};}};
 try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
